/** A frame from the extension. */
export type ClientFrame =
  | {
      api: number[];
      extension: string;
      type: 'hello';
    }
  | {
      id: number;
      method: string;
      params?: unknown;
      type: 'call';
    }
  | {
      id: number;
      type: 'cancel';
    };

/** A frame from the supervisor (or, for `error` with code `not-running` / `peer-not-allowed`, from the relay). */
export type ServerFrame =
  | {
      /** The API version chosen: the highest both sides speak. */
      api: number;
      /** The companion's version. */
      companion: string;
      limits: AnnouncedLimits;
      /** The methods this companion offers; the extension hides what is missing. */
      methods: string[];
      /** Always `macos`. */
      platform: string;
      /** The version of the pinned server the companion runs. */
      server: string;
      type: 'welcome';
    }
  | {
      id: number;
      result: unknown;
      type: 'result';
    }
  | {
      error: ErrorBody;
      id?: number | null;
      type: 'error';
    }
  | {
      data: unknown;
      id: number;
      seq: number;
      type: 'stream';
    }
  | {
      data: unknown;
      name: string;
      project?: string | null;
      type: 'event';
    }
  | {
      data: string;
      id?: number | null;
      last: boolean;
      seq: number;
      type: 'chunk';
    };

